package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;
public final class FrozenRoadRetentionTest {public static void main(String[] args)throws Exception{Path dir=Paths.get(args[0]),snapshots=Paths.get(args[1]);int snapshotsCount=0,cells=0,rejected=0;
try(DirectoryStream<Path> files=Files.newDirectoryStream(dir,"race-background-*.nrb")){for(Path file:files){NativeSceneSnapshot scene=new NativeBackgroundScene(Files.readAllBytes(file)).sky.scene;byte[][] proofs=new byte[scene.geometryCount()][];for(int i=0;i<proofs.length;i++)proofs[i]=Files.readAllBytes(dir.resolve("owner-"+scene.geometry(i).serial+".nrp"));NativeRoadHistory[] histories=new NativeRoadHistory[scene.geometryCount()];for(int i=0;i<histories.length;i++)histories[i]=new NativeRoadHistory(Files.readAllBytes(snapshots.resolve("owner-"+scene.geometry(i).serial+".nrh")));NativeRoadRetention retention=new NativeRoadRetention(scene,histories,proofs);if(!retention.belongsTo(scene))throw new AssertionError("Scene binding");byte[] expected=Files.readAllBytes(dir.resolve("retention-"+scene.refresh+".ref"));ByteBuffer ref=ByteBuffer.wrap(expected).order(ByteOrder.LITTLE_ENDIAN);int count=ref.getInt();int[] actual=new int[38400];java.util.Arrays.fill(actual,-1);for(int i=0;i<retention.count();i++){NativeRoadRetention.Draw draw=retention.draw(i);int[] records=draw.records();ByteBuffer texture=retention.texture(draw);for(int j=0;j<records.length;j+=3){int at=records[j+1]*240+records[j];if(actual[at]>=0)throw new AssertionError("Duplicate owner");actual[at]=texture.get(records[j+2])&255;}}int found=0;for(int v:actual)if(v>=0)found++;if(found!=count||found!=retention.cells())throw new AssertionError("Coverage");for(int i=0;i<count;i++){int cell=ref.getInt(),value=ref.getInt();if(actual[cell]!=value)throw new AssertionError("Retained source value");}cells+=count;snapshotsCount++;byte[] valid=proofs[0];int selected=-1;for(int cell=0;cell<38400;cell++)if(valid[80+cell]==1){selected=cell;break;}if(selected<0)throw new AssertionError("No road ownership");proofs[0]=valid.clone();ByteBuffer changed=ByteBuffer.wrap(proofs[0]).order(ByteOrder.LITTLE_ENDIAN);changed.putInt(38480+selected*4,changed.getInt(38480+selected*4)^1);try{new NativeRoadRetention(scene,histories,proofs);throw new AssertionError("Wrong writer accepted");}catch(IllegalArgumentException expectedFailure){rejected++;}proofs[0]=valid.clone();ByteBuffer.wrap(proofs[0]).order(ByteOrder.LITTLE_ENDIAN).putLong(24,scene.epoch+1);try{new NativeRoadRetention(scene,histories,proofs);throw new AssertionError("Wrong epoch accepted");}catch(IllegalArgumentException expectedFailure){rejected++;}}}if(snapshotsCount!=9||cells!=100870||rejected!=18)throw new AssertionError("Incomplete frozen scene checks");System.out.println("PASS_FROZEN_ROAD_RETENTION snapshots="+snapshotsCount+" source_cells="+cells+" stale_or_writer_rejected="+rejected);}}

